const items = $input.all();
const results = [];

for (const item of items) {
  const d = item.json;
  const name = d.userName || 'Athlete';
  const sessions = d.weekSessions || 0;
  const goalWeight = d.goalWeight || null;
  const currentWeight = d.latestWeight || null;
  const lbsLeft = (goalWeight && currentWeight) ? (currentWeight - goalWeight).toFixed(1) : null;

  let msg;
  if (sessions >= 4) {
    msg = `🔥 ${name}, ${sessions} sessions this week — you're on track! ${lbsLeft ? `${lbsLeft} lbs from your goal.` : ''} Keep the streak alive.`;
  } else if (sessions >= 2) {
    msg = `💪 ${name}, good start (${sessions} sessions). ${4 - sessions} more this week to hit your target. You've got time.`;
  } else {
    msg = `⚡ ${name}, new week, clean slate. Your plan is ready — let's go!`;
  }

  // Milestone check — dynamic based on user's goal, not hardcoded weight
  let milestoneMsg = null;
  if (goalWeight && currentWeight) {
    const pct = Math.round(((d.startWeight || currentWeight + 20) - currentWeight) / ((d.startWeight || currentWeight + 20) - goalWeight) * 100);
    if (pct >= 25 && pct < 30) milestoneMsg = `🏆 ${name} — you just crossed 25% of the way to your goal!`;
    if (pct >= 50 && pct < 55) milestoneMsg = `🏆 ${name} — HALFWAY THERE! Keep going.`;
    if (pct >= 75 && pct < 80) milestoneMsg = `🏆 ${name} — 75% to goal. The finish line is real now.`;
  }

  results.push({ json: { userId: d.userId, msg, milestoneMsg } });
}

return results;

const items = $input.all();
items.forEach(i => console.log('Streak notification:', i.json.userId, i.json.msg));
return items;
